SELECT PL.PRODUCT_CODE AS "PRODUCT_CODE", PL.PRODUCT_NAME AS "PRODUCT_NAME", PL.PRODUCT_NAME_ENG AS "PRODUCT_NAME_ENG", PL.FLOWCHART_COMMENT AS "FLOWCHART_COMMENT", FF.ORIGIN_FILE_NAME AS "FILE_NAME", TO_CHAR(PL.CREATE_DATE, 'YYYY-MM-DD') AS "CREATE_DATE" FROM PRODUCT_LINE PL
LEFT JOIN ( SELECT X.COMPANY_CODE, X.FLOWCHART_CODE, X.ORIGIN_FILE_NAME FROM ( SELECT F.COMPANY_CODE, F.FLOWCHART_CODE, F.ORIGIN_FILE_NAME, ROW_NUMBER() OVER ( PARTITION BY F.COMPANY_CODE, F.FLOWCHART_CODE ORDER BY F.FILE_SEQ ) AS RN FROM FLOWCHART_FILE F ) X WHERE X.RN = 1 ) FF ON FF.COMPANY_CODE = PL.COMPANY_CODE AND FF.FLOWCHART_CODE = PL.PRODUCT_CODE
WHERE PL.COMPANY_CODE = #{COMPANY_CODE}
AND PL.PRODUCT_CODE IN
